#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int h, w;
    long long limit;
    cin >> h >> w >> limit;
    vector<string> g(h);
    for (auto &row : g) cin >> row;
    // BFS by distance; layers beyond the limit are not expanded
    vector<int> dist(h * w, -1);
    deque<int> q = {0};
    dist[0] = 0;
    const int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    while (!q.empty()) {
        int cur = q.front();
        q.pop_front();
        int r = cur / w, c = cur % w, d = dist[cur];
        if (r == h - 1 && c == w - 1) { cout << (d <= limit ? "Yes" : "No") << "\n"; return 0; }
        if (d >= limit) continue;
        for (int k = 0; k < 4; k++) {
            int a = r + dr[k], b = c + dc[k];
            if (a >= 0 && a < h && b >= 0 && b < w && g[a][b] == '.' && dist[a * w + b] < 0) {
                dist[a * w + b] = d + 1;
                q.push_back(a * w + b);
            }
        }
    }
    cout << "No\n";
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int h = (int) nextLong(), w = (int) nextLong();
        long limit = nextLong();
        char[][] g = new char[h][];
        for (int i = 0; i < h; i++) g[i] = next().toCharArray();
        // BFS by distance; layers beyond the limit are not expanded
        int[] dist = new int[h * w];
        java.util.Arrays.fill(dist, -1);
        int[] q = new int[h * w];
        int head = 0, tail = 0;
        q[tail++] = 0;
        dist[0] = 0;
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        while (head < tail) {
            int cur = q[head++], r = cur / w, c = cur % w, d = dist[cur];
            if (r == h - 1 && c == w - 1) { System.out.println(d <= limit ? "Yes" : "No"); return; }
            if (d >= limit) continue;
            for (int k = 0; k < 4; k++) {
                int a = r + dr[k], b = c + dc[k];
                if (a >= 0 && a < h && b >= 0 && b < w && g[a][b] == '.' && dist[a * w + b] < 0) {
                    dist[a * w + b] = d + 1;
                    q[tail++] = a * w + b;
                }
            }
        }
        System.out.println("No");
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	h, w, limit := nextInt(), nextInt(), nextInt()
	g := make([]string, h)
	for i := range g {
		sc.Scan()
		g[i] = sc.Text()
	}
	// BFS by distance; layers beyond the limit are not expanded
	dist := make([]int, h*w)
	for i := range dist {
		dist[i] = -1
	}
	q := []int{0}
	dist[0] = 0
	dr := [4]int{1, -1, 0, 0}
	dc := [4]int{0, 0, 1, -1}
	for head := 0; head < len(q); head++ {
		cur := q[head]
		r, c, d := cur/w, cur%w, dist[cur]
		if r == h-1 && c == w-1 {
			if d <= limit {
				fmt.Println("Yes")
			} else {
				fmt.Println("No")
			}
			return
		}
		if d >= limit {
			continue
		}
		for k := 0; k < 4; k++ {
			a, b := r+dr[k], c+dc[k]
			if a >= 0 && a < h && b >= 0 && b < w && g[a][b] == '.' && dist[a*w+b] < 0 {
				dist[a*w+b] = d + 1
				q = append(q, a*w+b)
			}
		}
	}
	fmt.Println("No")
}
